package sem

import (
	"context"
	"errors"
	"fmt"
	"math"
	"path"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/entireio/entire-graph/internal/gitutil"
)

// maxDiffFileBytes caps how large a blob the semantic diff will materialize,
// per side. It is deliberately the same ceiling the snapshot parser uses
// (defaultMaxParseBytes): a file the graph declines to parse is not one the
// diff should read twice in order to parse it anyway.
const maxDiffFileBytes = defaultMaxParseBytes

// Keep metadata prefetch bounded so a short analysis budget does not inspect an
// entire huge range before the per-file budget check can stop it.
const analyzeMetadataPrimeFiles = 128

func AnalyzeGitRange(ctx context.Context, repo, base, head string, paths []string) (Result, error) {
	return AnalyzeGitRangeWithOptions(ctx, repo, base, head, paths, AnalyzeOptions{})
}

// AnalyzeOptions configures optional semantic diff behavior.
type AnalyzeOptions struct {
	Progress func(AnalyzeProgressEvent)
	// MaxDuration is the overall wall-clock budget for the analysis. When it
	// runs out the analysis stops cleanly and returns the partial result built
	// so far, with machine-readable W_ANALYSIS_BUDGET_EXCEEDED warnings
	// enumerating what was skipped. Zero means no budget (historical
	// behavior).
	MaxDuration time.Duration
}

// AnalyzeProgressEvent reports coarse progress for a semantic diff.
type AnalyzeProgressEvent struct {
	Phase      string
	FilesDone  int
	FilesTotal int
	// Path is the file currently being processed ("" on phase boundaries).
	Path    string
	Elapsed time.Duration
}

// changedFileScan is one changed file's share of the parse phase: the delta it
// produced and the warnings it raised, held until the reducer folds them in
// file order.
//
// stopped records that the worker ran out of budget. The reducer also checks
// the deadline in file order because earlier work can consume the budget while
// this result waits in the pipeline.
type changedFileScan struct {
	delta    *fileDelta
	warnings []ProviderWarning
	stopped  bool
	err      error
}

// errAnalyzeParseStopped unwinds one window when the budget runs out. It never
// reaches a caller: the parse reports a stop with warnings and its partial
// deltas, exactly as the sequential loop did.
var errAnalyzeParseStopped = errors.New("analyze parse stopped")

// AnalyzeGitRangeWithOptions analyzes a Git range with optional progress reporting.
func AnalyzeGitRangeWithOptions(ctx context.Context, repo, base, head string, paths []string, options AnalyzeOptions) (Result, error) {
	if err := EnsureGitMetadataSafeForSubprocess(repo); err != nil {
		return Result{}, err
	}
	started := time.Now()
	var deadline time.Time
	if options.MaxDuration > 0 {
		deadline = started.Add(options.MaxDuration)
	}
	overBudget := func() bool {
		return !deadline.IsZero() && !time.Now().Before(deadline)
	}
	var lastEmit time.Time
	// force emits phase boundaries unconditionally; per-file events are
	// throttled to roughly one per second so slow files stay visible without
	// flooding stderr on fast ones.
	emitProgressEvent := func(phase string, filesDone, filesTotal int, path string, force bool) {
		if options.Progress == nil {
			return
		}
		if !force && time.Since(lastEmit) < time.Second {
			return
		}
		lastEmit = time.Now()
		options.Progress(AnalyzeProgressEvent{
			Phase:      phase,
			FilesDone:  filesDone,
			FilesTotal: filesTotal,
			Path:       path,
			Elapsed:    time.Since(started),
		})
	}
	emitProgress := func(phase string, filesDone, filesTotal int) {
		emitProgressEvent(phase, filesDone, filesTotal, "", true)
	}

	// Bind both caller-facing revision labels to immutable raw trees before any
	// discovery or content read. A branch can advance between ChangedFiles, the
	// size probe, and ShowFile; resolving each operation through the original
	// label would then compare bytes from different ranges and could invalidate
	// the read ceiling. Trees preserve the command's historical tree-ish input
	// contract; requiring commits would reject valid tree OIDs and expressions.
	// gitutil disables replace refs for every subprocess, so refs/replace cannot
	// mutate either pinned tree between discovery, metadata, content, and grep.
	// When both labels are byte-identical, reuse the first resolution so a ref
	// advance between subprocesses cannot turn an intended empty diff into an
	// old-tree/new-tree comparison. Keep the labels below for result provenance.
	pinnedBase, pinnedHead, rootRelativeNames, err := resolveDiffTrees(ctx, repo, base, head, gitutil.RevParse)
	if err != nil {
		return Result{}, err
	}
	// ChangedFiles intentionally retains the caller's cwd so explicit path
	// arguments keep Git's native --repo-relative meaning. Its emitted names,
	// however, are relative to the compared tree. Perform every subsequent
	// object read and grep from Git's command root so a repository subdirectory
	// is not applied again when pinnedBase/pinnedHead are already subtree OIDs.
	objectRepo, err := gitutil.RepoCommandRoot(ctx, repo)
	if err != nil {
		return Result{}, err
	}

	emitProgress("discover", 0, 0)
	changed, err := gitutil.ChangedFiles(ctx, repo, pinnedBase, pinnedHead, paths)
	if err != nil {
		return Result{}, err
	}
	// Every graph command honors a repo-root .graphignore and the vendored-tree
	// heuristic (see the `index` help text and docs/operations.md). The
	// snapshot/search family applies both through openSource; the diff family
	// applied neither, so a tracked-but-vendored or generated tree that the
	// graph never indexes still produced entity changes here. A consumer that
	// builds its index from `snapshot` and updates it from `diff` received
	// symbols for files that its index has no record of and never will.
	basePolicy, headPolicy, err := newDiffIndexPolicies(ctx, objectRepo, pinnedBase, pinnedHead, rootRelativeNames, changed, overBudget)
	if err != nil {
		return Result{}, err
	}
	policySource := changed
	if len(paths) > 0 {
		// A pathspec narrows what Git reports, but not what an exclusion rule
		// decides: a root .gitignore edited outside the requested scope still
		// changes membership inside it, and the scoped list cannot show that.
		// Ask Git for the policy files directly, anchored at the repository root
		// with :(top) so the caller's cwd does not narrow them a second time.
		policySource, err = gitutil.ChangedFiles(ctx, repo, pinnedBase, pinnedHead, indexPolicyPathspecs)
		if err != nil {
			return Result{}, err
		}
	}
	policyWarnings := indexPolicyChangeWarnings(policySource, basePolicy)
	changed = admitChangedFiles(changed, basePolicy, headPolicy)
	emitProgress("parse", 0, len(changed))
	parser := TreeSitterParser{}
	baseReader := gitutil.NewLimitedFileReader(ctx, objectRepo, pinnedBase, maxDiffFileBytes)
	headReader := gitutil.NewLimitedFileReader(ctx, objectRepo, pinnedHead, maxDiffFileBytes)
	baseReader.SetDeadline(deadline)
	headReader.SetDeadline(deadline)
	defer func() {
		_ = baseReader.Close()
		_ = headReader.Close()
	}()
	// SchemaVersion is set here, at the one place a content-bearing Result is
	// constructed; every caller (AnalyzeGitRange, AnalyzeCheckpoint, and the
	// diff/analyze CLI handlers that call through them) inherits it.
	result := Result{Base: base, Head: head, SchemaVersion: SchemaVersion}
	result.Warnings = append(result.Warnings, policyWarnings...)
	var deltas []*fileDelta
	appendBudgetWarnings := func(start int) {
		for _, skipped := range changed[start:] {
			result.Warnings = append(result.Warnings, budgetSkippedFileWarning(skipped.Path, start, len(changed), options.MaxDuration))
		}
	}
	// Each changed file is read and parsed independently, so the files in one
	// metadata window run on workers while a reducer folds their deltas and
	// warnings in the original file order. Windows stay sequential: priming is
	// what makes the reads cheap, and it is defined over a run of files.
	processChangedFile := func(i int, file gitutil.ChangedFile) changedFileScan {
		var scan changedFileScan
		// Avoid starting more parse work after the budget expires. The reducer
		// independently checks the deadline before accepting buffered results.
		if overBudget() {
			scan.stopped = true
			return scan
		}
		path := file.Path
		oldPath := file.OldPath
		if oldPath == "" {
			oldPath = path
		}
		// The status this file is REPORTED under, when that differs from the
		// status the read plan below runs on. A one-sided symlink type change is
		// READ as if it were an addition or a deletion, because only one side
		// holds analyzable content, but the path itself was neither added nor
		// deleted — it changed type — so the delta keeps the status Git gave it.
		//
		// It stays empty for every other entry on purpose. A later restatement
		// — a rename across the supported/unsupported boundary — also rewrites
		// file.Status, and there the NEW value is the one that must be reported:
		// the range really did delete or add the only side the graph holds.
		// Freezing Git's status for every entry reported those renames as "R".
		var reportedStatus string
		beforeInvalidPath := file.Status != "A" && !gitutil.IsCanonicalGitTreePath(oldPath)
		afterInvalidPath := file.Status != "D" && !gitutil.IsCanonicalGitTreePath(path)
		if beforeInvalidPath || afterInvalidPath {
			warningPath := path
			detail := "head path is not a canonical Git tree path"
			if beforeInvalidPath && !afterInvalidPath {
				warningPath = oldPath
				detail = "base path is not a canonical Git tree path"
			} else if beforeInvalidPath && afterInvalidPath {
				detail = "base and head paths are not canonical Git tree paths"
			}
			scan.warnings = append(scan.warnings, diffFileReadWarning(warningPath, detail))
			return scan
		}

		// A symbolic link is stored as a blob whose bytes are its target path,
		// so it reaches the readers below indistinguishable from a one-line
		// source file: `alias.py` holding "pkg/real.py" parses cleanly as
		// Python and yields a phantom module entity, while `alias.go` holding
		// "pkg/real.go" fails to parse and reports E_PARSE_ERROR against a file
		// that is not source at all. Mode is the only signal that separates
		// them, so classify here — alongside the gitlink handling below, which
		// this mirrors — rather than reading content that cannot be analyzed.
		beforeSymlink := file.Status != "A" && file.OldMode == gitutil.SymlinkMode
		afterSymlink := file.Status != "D" && file.NewMode == gitutil.SymlinkMode
		if beforeSymlink || afterSymlink {
			warningPath := path
			detail := "head version is a symbolic link, not file content"
			if beforeSymlink && !afterSymlink {
				warningPath = oldPath
				detail = "base version is a symbolic link, not file content"
			} else if beforeSymlink && afterSymlink {
				detail = "base and head versions are symbolic links, not file content"
			}
			// A path can change TYPE between a regular file and a symbolic
			// link, which Git reports as status `T` with one mode 100644 and the
			// other 120000. Only the symlink side is unanalyzable; the other
			// side is ordinary source whose symbols genuinely appear or
			// disappear at this commit. Skipping BOTH sides discarded that:
			// replacing a source file with a link reported no removals, and
			// replacing a link with a source file reported no additions, so a
			// symbol that really left the tree was invisible in the diff. Read
			// the file side as the one-sided change it is and skip only the
			// link side. `A` and `D` are excluded because they have only one
			// side to begin with, and it is the symlink.
			effect := "file skipped; the Git tree entry is a symbolic link, so its changes are not analyzed"
			typeChange := beforeSymlink != afterSymlink && file.Status != "A" && file.Status != "D"
			if typeChange {
				effect = "symbolic-link side skipped; the file side is analyzed as a one-sided change"
				reportedStatus = file.Status
				if afterSymlink {
					file.Status = "D"
				} else {
					file.Status = "A"
				}
			}
			scan.warnings = append(scan.warnings, ProviderWarning{
				Code:                 "W_UNSUPPORTED_FILE",
				Severity:             "info",
				FilePath:             warningPath,
				EffectOnCompleteness: effect,
				Detail:               detail,
			})
			if !typeChange {
				return scan
			}
		}

		var before, after string
		var beforeOK, afterOK bool
		// Fast-path: a file WITH a recognized-unsupported extension classifies without reading
		// its blobs — shebang sniffing only matters for extensionless files. Avoids loading a
		// large binary twice just to conclude "unsupported"; the marker below needs no content.
		if extensionUnsupported(oldPath) && extensionUnsupported(path) {
			beforeOK = file.Status != "A"
			afterOK = file.Status != "D"
		} else {
			// Both sides are read under the same ceiling the snapshot parser
			// uses. A semantic diff holds TWO blobs of one file at once, so an
			// unbounded read here sets this command's memory and time by the
			// largest object in the range rather than by anything the caller
			// chose -- and unlike the snapshot readers, nothing downstream
			// would have declined to parse it.
			var beforeRead, afterRead gitutil.LimitedFileResult
			// Declared here, not shared with the enclosing function: this runs on
			// a worker.
			var err error
			if file.Status != "A" {
				beforeRead, err = baseReader.ReadFile(oldPath)
				if err != nil {
					scan.err = err
					return scan
				}
				before, beforeOK = beforeRead.Content, beforeRead.Status == gitutil.LimitedFileContent
			}
			if file.Status != "D" {
				afterRead, err = headReader.ReadFile(path)
				if err != nil {
					scan.err = err
					return scan
				}
				after, afterOK = afterRead.Content, afterRead.Status == gitutil.LimitedFileContent
			}

			beforeMissing := file.Status != "A" && beforeRead.Status == gitutil.LimitedFileMissing
			afterMissing := file.Status != "D" && afterRead.Status == gitutil.LimitedFileMissing
			if beforeMissing || afterMissing {
				warningPath := path
				detail := "head version was missing after changed-file discovery"
				if beforeMissing && !afterMissing {
					warningPath = oldPath
					detail = "base version was missing after changed-file discovery"
				} else if beforeMissing && afterMissing {
					detail = "base and head versions were missing after changed-file discovery"
				}
				scan.warnings = append(scan.warnings, diffFileReadWarning(warningPath, detail))
			}

			beforeUnreadable := file.Status != "A" && beforeRead.Status == gitutil.LimitedFileUnreadable
			afterUnreadable := file.Status != "D" && afterRead.Status == gitutil.LimitedFileUnreadable
			if beforeUnreadable || afterUnreadable {
				warningPath := path
				detail := "head version references an unreadable Git blob object"
				if beforeUnreadable && !afterUnreadable {
					warningPath = oldPath
					detail = "base version references an unreadable Git blob object"
				} else if beforeUnreadable && afterUnreadable {
					detail = "base and head versions reference unreadable Git blob objects"
				}
				scan.warnings = append(scan.warnings, diffFileReadWarning(warningPath, detail))
			}

			beforeNonBlob := file.Status != "A" && beforeRead.Status == gitutil.LimitedFileNonBlob
			afterNonBlob := file.Status != "D" && afterRead.Status == gitutil.LimitedFileNonBlob
			if beforeNonBlob || afterNonBlob {
				warningPath := path
				detail := "head version is a non-blob Git tree entry"
				if beforeNonBlob && !afterNonBlob {
					warningPath = oldPath
					detail = "base version is a non-blob Git tree entry"
				} else if beforeNonBlob && afterNonBlob {
					detail = "base and head versions are non-blob Git tree entries"
				}
				scan.warnings = append(scan.warnings, diffNonBlobWarning(warningPath, detail))
			}

			beforeOversize := file.Status != "A" && beforeRead.Status == gitutil.LimitedFileOversize
			afterOversize := file.Status != "D" && afterRead.Status == gitutil.LimitedFileOversize
			if beforeOversize || afterOversize {
				warningPath := path
				detail := "head version is above the diff read cap"
				if beforeOversize && !afterOversize {
					warningPath = oldPath
					detail = "base version is above the diff read cap"
				} else if beforeOversize && afterOversize {
					detail = "base and head versions are above the diff read cap"
				}
				scan.warnings = append(scan.warnings, diffFileTooLargeWarning(warningPath, detail))
			}

			beforeUnaddressable := file.Status != "A" && beforeRead.Status == gitutil.LimitedFileUnaddressable
			afterUnaddressable := file.Status != "D" && afterRead.Status == gitutil.LimitedFileUnaddressable
			if beforeUnaddressable || afterUnaddressable {
				warningPath := path
				detail := "head path could not be resolved within bounded Git metadata traversal"
				if beforeUnaddressable && !afterUnaddressable {
					warningPath = oldPath
					detail = "base path could not be resolved within bounded Git metadata traversal"
				} else if beforeUnaddressable && afterUnaddressable {
					detail = "base and head paths could not be resolved within bounded Git metadata traversal"
				}
				scan.warnings = append(scan.warnings, diffFileReadWarning(warningPath, detail))
			}
			if beforeMissing || afterMissing || beforeUnreadable || afterUnreadable || beforeNonBlob || afterNonBlob || beforeOversize || afterOversize || beforeUnaddressable || afterUnaddressable {
				return scan
			}
		}

		// Support is content-aware: extensionless executables can still route to a
		// parser through their shebang, so each existing side is classified
		// independently.
		//
		// A side with no parser holds nothing in the graph — that is what "the
		// graph does not index .txt" means — so a rename across the parser
		// boundary is a file leaving or entering the index, and the honest delta
		// is the removals or additions that a snapshot of each side would show.
		// This used to suppress the whole record to avoid a "one-sided phantom
		// remove/add", but the removals are not phantom: `x.go` -> `x.txt` really
		// does take Run out of every snapshot, and suppressing it left a consumer
		// unable to retire the old compound-v1 IDs while the warning named only
		// the head path. The marker below still says the comparison is one-sided.
		_, beforeSupported := languageForContent(oldPath, before)
		_, afterSupported := languageForContent(path, after)
		beforeUnsupported := beforeOK && !beforeSupported
		afterUnsupported := afterOK && !afterSupported
		if beforeUnsupported || afterUnsupported {
			warningPath := path
			detail := "head version has no supported parser"
			if beforeUnsupported && !afterUnsupported {
				warningPath = oldPath
				detail = "base version has no supported parser"
			} else if beforeUnsupported && afterUnsupported {
				detail = "base and head versions have no supported parser"
			}
			effect := "file skipped; no parser for this file type, so its changes are not analyzed"
			if beforeOK && afterOK && beforeUnsupported != afterUnsupported {
				effect = "one side has no parser, so its symbols are reported as leaving or entering the graph rather than compared"
			}
			scan.warnings = append(scan.warnings, ProviderWarning{
				Code:                 "W_UNSUPPORTED_FILE",
				Severity:             "info",
				FilePath:             warningPath,
				EffectOnCompleteness: effect,
				Detail:               detail,
			})
			// Only a change with BOTH sides present, exactly one of them parseable,
			// says anything about the graph: the file crossed the boundary and
			// its symbols entered or left the index.
			//
			// Every other shape must stop here. Two unsupported sides are in no
			// snapshot at either end. An ADDED or DELETED unsupported file has
			// only one side at all, so `beforeUnsupported && afterUnsupported` was
			// false for it and it fell through to moduleScopeChange, which happily
			// emitted an added/removed module for a path no snapshot indexes —
			// the same invented record this branch exists to prevent, reached by
			// forgetting that an absent side is not an unsupported one.
			//
			// Mutation-checking shows the restatement below happens to neutralize
			// the added/deleted shape on its own, so this guard changes no output
			// today. It is kept because that neutralization is an accident of
			// three other decisions lining up — the restatement empties both
			// sides, moduleScopeChange declines an empty pair, pathScopeChange
			// declines an unchanged path — and any one of them moving would put
			// the invented record back with nothing to catch it.
			if !(beforeOK && afterOK && beforeUnsupported != afterUnsupported) {
				return scan
			}
			// The unparseable side is not in the graph, so the range did not
			// rename a file the graph holds: it removed one or added one. Restate
			// it as that, exactly as the index policy restates a rename across the
			// exclusion boundary, so the reported path and language are the
			// indexed side's and no consumer is handed `sample.ps1` labelled Go.
			if afterUnsupported {
				path, after, afterOK = oldPath, "", false
				file.Status, file.OldPath = "D", ""
			} else {
				oldPath, before, beforeOK = path, "", false
				file.Status, file.OldPath = "A", ""
			}
		}

		beforeEntities, beforeLanguage, beforeStatus := parser.ParseWithStatus(oldPath, before)
		afterEntities, afterLanguage, afterStatus := parser.ParseWithStatus(path, after)
		// The head side names the file as it now is, and a rename can cross
		// extensions: mod.js -> mod.ts is one file whose language changed with
		// its path. The graph indexes the head path under the head parser's
		// language, so reporting the base label here would disagree with every
		// snapshot of that tree. Fall back to the base label only when there is
		// no head version to ask — a deletion — or when it has no opinion.
		language := afterLanguage
		if (file.Status == "D" || language == "") && beforeLanguage != "" {
			language = beforeLanguage
		}
		// A parse failure on either side degrades the diff. A TOTAL failure
		// (ParseError with ZERO recovered entities) gives compareEntities no
		// signal at all and would make it report every entity on that side as
		// a phantom removed/added, so the delta is skipped and a
		// machine-readable warning is surfaced instead. A PARTIAL recovery
		// (ParseError with some entities extracted) keeps the diff — the
		// recovered changes are real — but is still flagged with a warning,
		// because symbols missing from the recovered set can surface as
		// phantom removed/added. A validly-emptied file (ParseError false) is
		// never suppressed or flagged, so its real removed changes stand.
		//
		// A failed parse is this provider failing to READ the file, not evidence
		// that the file is empty. The symbols are most likely still there, so
		// reporting them as removed would state a deletion that did not happen —
		// the phantom the suppression here exists to prevent, and a different
		// situation from a side the graph does not index at all (above), where
		// their absence is a fact rather than a blind spot.
		//
		// ParseStatus.Partial marks a status whose output is valid even when it
		// is empty, so it is never a total failure however few entities came
		// back. A depth-truncated walk (E_PARSE_DEPTH_EXCEEDED) is the case:
		// the tree parsed and the walk stopped, so zero entities means "no
		// declarations above the limit", not "no signal" — treating it as total
		// would suppress the whole file's delta, losing for instance the
		// module-scope change of a Python file whose only statement is a
		// deeply parenthesized module-level assignment.
		// A side that is both malformed AND depth-truncated (DepthExceeded set,
		// Partial deliberately false — see the depthExceeded && root.HasError()
		// case in parser.go) is a total failure regardless of how many entities
		// it recovered before hitting either problem: those entities may be
		// wrong, not merely an incomplete-but-trustworthy subset, so they must
		// not be compared against the other side any more than a zero-entity
		// failure would be. Without this, a shallow entity recovered before the
		// combined failure fell through to the kept-diff path below with
		// oneSidedSuppressed never set (that check reads Partial, which this
		// case leaves false), reopening exactly the phantom
		// removed/added-below-the-depth-limit class this status exists to
		// prevent.
		afterParseFailed := afterStatus.ParseError && !afterStatus.Partial && (len(afterEntities) == 0 || afterStatus.DepthExceeded)
		beforeParseFailed := beforeStatus.ParseError && !beforeStatus.Partial && (len(beforeEntities) == 0 || beforeStatus.DepthExceeded)
		if afterParseFailed || beforeParseFailed {
			status, warnPath := afterStatus, path
			if !afterParseFailed {
				status, warnPath = beforeStatus, oldPath
			}
			scan.warnings = append(scan.warnings, parseFailureWarning(warnPath, status, diffSuppressed))
			return scan
		}
		// A depth-truncated side that recovered ZERO entities is a valid
		// partial result — the tree parsed — that nonetheless carries NO
		// entity-level information: the walk stopped before it reached any
		// declaration, so "this side declares nothing" is indistinguishable
		// from "every declaration is hidden below the limit". Comparing it
		// against a populated side made compareEntities emit every symbol on
		// that side as removed (or added): the same phantom class the
		// total-failure path above exists to prevent, reached through a
		// WELL-FORMED file, and reconcileMoves can then promote those phantoms
		// into cross-file MOVES. So the entity comparison is skipped for this
		// file and only its module-scope change is reported, which is real —
		// the bytes did change. The cost is under-reporting when that side
		// genuinely stopped declaring anything; the warning below says so
		// rather than claiming a complete diff.
		//
		// Three cases stay deliberately distinct:
		//   truncated, zero entities  -> module-scope change only (here)
		//   truncated, some entities  -> entity diff kept: fewer, but correct
		//   not truncated, zero       -> entity diff kept: the removals are real
		//
		// Only an existing side can lack signal: on an add/delete the missing
		// side parses no content, and its emptiness is the real change.
		beforeNoEntitySignal := beforeOK && beforeStatus.Partial && len(beforeEntities) == 0
		afterNoEntitySignal := afterOK && afterStatus.Partial && len(afterEntities) == 0
		entitiesSkipped := beforeNoEntitySignal || afterNoEntitySignal
		// A truncated side that DID recover entities (the case above is the
		// zero-entity one) still cannot tell "unchanged, just below the walk
		// limit" apart from "genuinely removed": both look like a key missing
		// from that side's recovered set. A matched key present on BOTH sides
		// carries no such ambiguity — it was extracted from both trees, so its
		// signature/body comparison is exact — but a key found on only one
		// side is exactly the shape a truncated side manufactures for every
		// declaration hidden below the limit, real removal or not. Suppress
		// one-sided results (including the rename reconciliation, which is
		// built from those same one-sided sets) whenever either side is
		// truncated; matched changes are unaffected.
		//
		// That ambiguity only exists when BOTH revisions exist: on an add or a
		// delete, the missing side has no tree to hide anything in, so every
		// entity recovered from the truncated existing side is unambiguously a
		// real addition or removal, not a truncation artifact. Gating on
		// beforeOK && afterOK keeps that case out of suppression instead of
		// collapsing a real symbol-level add/delete into a synthetic
		// module-scope change with none of its actual entities reported.
		oneSidedSuppressed := beforeOK && afterOK && (beforeStatus.Partial || afterStatus.Partial)
		if afterStatus.ParseError || beforeStatus.ParseError {
			status, warnPath := afterStatus, path
			// Warn about the side that lost the signal when one did, so the
			// detail names the truncated file rather than the other revision.
			if !afterStatus.ParseError || (entitiesSkipped && !afterNoEntitySignal) {
				status, warnPath = beforeStatus, oldPath
			}
			outcome := diffKept
			if entitiesSkipped {
				outcome = diffEntitiesSkipped
			}
			scan.warnings = append(scan.warnings, parseFailureWarning(warnPath, status, outcome))
		}
		// A side with no parser holds nothing in the graph, so emptying it turns
		// the comparison below into the removals or additions a snapshot of each
		// side would show. It sits beside the missing-revision emptying rather
		// than up with the truncation analysis because it is the same operation:
		// normalizing what this side is known to contain. The truncation checks
		// above are unaffected either way -- an unsupported side has no parser,
		// so it carries no ParseStatus.Partial for them to read.
		if beforeUnsupported {
			beforeEntities = nil
		}
		if afterUnsupported {
			afterEntities = nil
		}
		if !beforeOK {
			beforeEntities = nil
		}
		if !afterOK {
			afterEntities = nil
		}

		var changes []EntityChange
		var removed, added []Entity
		if !entitiesSkipped {
			changes, removed, added = compareEntities(beforeEntities, afterEntities, oneSidedSuppressed)
		}
		if len(changes) == 0 && len(removed) == 0 && len(added) == 0 {
			// The file changed but no named symbol did: the edit lives at
			// module scope (top-level statements, imports, comments). Surface
			// it as a synthetic module-level change instead of dropping it.
			mod, ok := moduleScopeChange(path, before, after, beforeOK, afterOK)
			if !ok {
				// A pure rename reaches here: both sides parse to the same
				// entities and the bytes are identical, so there is no content
				// change to report. The path still changed, and the path is a
				// component of every compound-v1 symbol ID in the file, so
				// every entity in it was re-identified. Report the path move so
				// the file is never absent from the diff.
				mod, ok = pathScopeChange(oldPath, path)
			}
			if !ok {
				return scan
			}
			changes = append(changes, mod)
		}
		deltaStatus := file.Status
		if reportedStatus != "" {
			deltaStatus = reportedStatus
		}
		scan.delta = &fileDelta{
			path:     path,
			oldPath:  file.OldPath,
			status:   deltaStatus,
			language: language,
			changes:  changes,
			removed:  removed,
			added:    added,
		}
		return scan
	}

	// Windows are sequential because priming is defined over a run of files;
	// the files inside one window run together. A window that goes over budget
	// stops the whole parse, and the reducer -- which sees files in order -- is
	// what decides where, so skipped-file warnings describe the accepted prefix.
	stopped := false
	for start := 0; start < len(changed) && !stopped; start += analyzeMetadataPrimeFiles {
		if overBudget() {
			appendBudgetWarnings(start)
			break
		}
		end := min(start+analyzeMetadataPrimeFiles, len(changed))
		basePaths := make([]string, 0, end-start)
		headPaths := make([]string, 0, end-start)
		for _, candidate := range changed[start:end] {
			oldCandidatePath := candidate.OldPath
			if oldCandidatePath == "" {
				oldCandidatePath = candidate.Path
			}
			if extensionUnsupported(oldCandidatePath) && extensionUnsupported(candidate.Path) {
				continue
			}
			if candidate.Status != "A" && gitutil.IsCanonicalGitTreePath(oldCandidatePath) {
				basePaths = append(basePaths, oldCandidatePath)
			}
			if candidate.Status != "D" && gitutil.IsCanonicalGitTreePath(candidate.Path) {
				headPaths = append(headPaths, candidate.Path)
			}
		}
		if err := baseReader.Prime(basePaths); err != nil {
			return Result{}, err
		}
		if err := headReader.Prime(headPaths); err != nil {
			return Result{}, err
		}
		// Component traversal observes the same deadline between metadata
		// subprocesses. Re-check immediately so this window and the rest
		// receive the ordinary budget warnings instead of being misreported as
		// unaddressable/read failures after Prime stopped at that deadline.
		if overBudget() {
			appendBudgetWarnings(start)
			break
		}
		windowErr := runIndexedPipeline(ctx, end-start, defaultProviderWorkerCount(),
			func(_ context.Context, j int) changedFileScan {
				return processChangedFile(start+j, changed[start+j])
			},
			func(j int, scan changedFileScan) error {
				if scan.err != nil {
					return scan.err
				}
				i := start + j
				// The budget decision comes before the progress event, as it did
				// in the sequential loop: a file the budget skips is reported as
				// skipped in the warnings, so announcing it as parsed first would
				// contradict the result the same run returns.
				if scan.stopped || overBudget() {
					appendBudgetWarnings(i)
					stopped = true
					return errAnalyzeParseStopped
				}
				emitProgressEvent("parse", i, len(changed), changed[i].Path, i > 0 && i%100 == 0)
				result.Warnings = append(result.Warnings, scan.warnings...)
				if scan.delta != nil {
					deltas = append(deltas, scan.delta)
				}
				return nil
			})
		if windowErr != nil && !errors.Is(windowErr, errAnalyzeParseStopped) {
			return Result{}, windowErr
		}
	}
	emitProgress("parse", len(changed), len(changed))
	baseCloseErr := baseReader.Close()
	headCloseErr := headReader.Close()
	if baseCloseErr != nil {
		return Result{}, baseCloseErr
	}
	if headCloseErr != nil {
		return Result{}, headCloseErr
	}

	emitProgress("reconcile", len(changed), len(changed))
	result.Warnings = append(result.Warnings, reconcileMoves(deltas)...)

	for _, delta := range deltas {
		changes := delta.changes
		for _, oldEntity := range delta.removed {
			changes = append(changes, removedChange(oldEntity))
		}
		for _, newEntity := range delta.added {
			changes = append(changes, addedChange(newEntity))
		}
		if len(changes) == 0 {
			continue
		}
		sortChanges(changes)
		result.Files = append(result.Files, FileChange{
			Path:     delta.path,
			OldPath:  delta.oldPath,
			Status:   delta.status,
			Language: delta.language,
			Changes:  changes,
		})
	}

	// The dependents scan reads the whole head tree, so it needs the head tree's
	// real rules rather than the ones the changed-file probe was allowed to skip.
	// Resolve them only when there is something to count, and only while the
	// budget still allows work: resolving lists the whole head tree and reads its
	// ignore files, and an exhausted range must return with its budget warning
	// rather than spend more time than the caller asked for. The scan below
	// re-checks the same deadline and stops immediately, so the policy it would
	// have used cannot matter then.
	dependentsPolicy := headPolicy
	if len(result.Files) > 0 && !overBudget() {
		dependentsPolicy, err = headPolicy.resolvedForTree(ctx, objectRepo, pinnedHead)
		if err != nil {
			return Result{}, err
		}
	}
	if err := addDependentCountsWithProgress(ctx, objectRepo, pinnedHead, &result, dependentsScanOptions{
		progress: func(done, total int, path string) {
			emitProgressEvent("dependents", done, total, path, path == "")
		},
		deadline: deadline,
		budget:   options.MaxDuration,
		admit:    dependentsPolicy.admitFunc(),
	}); err != nil {
		return Result{}, err
	}
	emitProgress("complete", len(changed), len(changed))
	return result, nil
}

// resolveDiffTrees pins both revision labels to immutable trees and reports
// whether ChangedFiles' names for the resulting range are repository-root
// relative.
//
// That last question decides whether any exclusion policy may be applied at all.
// ChangedFiles passes --no-relative, so a range between two COMMITS is named
// from the repository root, which is the namespace the root .graphignore and the
// vendored-tree rules are written in. A tree expression such as HEAD:scope names
// a subtree, and every emitted name is then relative to THAT tree: matching
// root-relative rules against those names both misses the rules that were meant
// to apply and fires rules that were not, which silently drops indexed files.
// There is no prefix to recover, because a tree object does not know its own
// path, so the only correct answer for a subtree range is to apply no policy.
// maxRevisionPeels bounds how many trailing ^{...} groups are stripped while
// deciding whether a label bottoms out at a commit. Each step costs a git
// subprocess, and no real revision expression stacks more than a couple.
const maxRevisionPeels = 4

// labelSelectsTreePath reports whether a revision label reaches INTO a tree
// rather than naming a revision.
//
// Resolving to a commit object is not sufficient evidence that a label named a
// commit: a gitlink resolves to one too. `HEAD:sub` on a submodule entry yields
// that submodule's commit, and a range over its tree is named relative to the
// SUBMODULE's root, not this repository's — so a superproject rule set matched
// against those names is the same category error as a subtree range. The probe
// happens to fail today because the submodule's objects usually are not in the
// superproject's object database, but an absorbed or fetched submodule puts them
// there, and correctness here should not rest on which objects a repository
// happens to hold.
//
// `:` is the only object-name syntax that reaches into a tree (`<rev>:<path>`
// and `:<stage>:<path>`), but not every colon is that syntax. Three forms carry
// colons that are data:
//
//	:/text                            a commit-message search; the colons are text
//	HEAD@{2026-08-27 12:34:56 +0000}  a reflog date selector
//	HEAD^{/release: fix}              a commit-message search from a starting point
//
// All three name a commit and reach into no tree, so only a colon outside every
// `@{...}` and `^{...}` block is the separator. Both brace forms are tracked, not
// just the one that happened to come up first: mistaking a commit for a subtree
// loses no data, but it silently withdraws the exclusion guarantee for the whole
// range, which is the kind of failure nothing downstream can notice.
func labelSelectsTreePath(label string) bool {
	if strings.HasPrefix(label, ":/") {
		return false
	}
	depth := 0
	for index := 0; index < len(label); index++ {
		switch label[index] {
		case '@', '^':
			if index+1 < len(label) && label[index+1] == '{' {
				depth++
				index++
			}
		case '}':
			if depth > 0 {
				depth--
			}
		case ':':
			if depth == 0 {
				return true
			}
		}
	}
	return false
}

func resolveDiffTrees(
	ctx context.Context,
	repo, base, head string,
	resolve func(context.Context, string, string) (string, error),
) (string, string, bool, error) {
	rootRelative := func(label, objectID string) bool {

package gitutil

import (
	"bufio"
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/entireio/entire-graph/internal/filedigest"
)

type ChangedFile struct {
	Status  string `json:"status"`
	Path    string `json:"path"`
	OldPath string `json:"old_path,omitempty"`
	// OldMode and NewMode are the Git tree entry modes for the base and head
	// sides ("100644", "100755", "120000" for a symbolic link, "160000" for a
	// gitlink, "000000" when that side does not exist). Callers need them
	// because mode decides whether a blob is file content at all: a symlink is
	// stored as a blob whose bytes are its target path, so nothing downstream
	// can tell it apart from a one-line source file by content or name.
	OldMode string `json:"old_mode,omitempty"`
	NewMode string `json:"new_mode,omitempty"`
}

// SymlinkMode is the Git tree entry mode for a symbolic link.
const SymlinkMode = "120000"

type FileCochange struct {
	Left  string
	Right string
	Count int
}

// GrepMatch is one matched substring from a tracked-worktree fixed-string grep.
type GrepMatch struct {
	Path string
	Text string
}

// RepoRoot reports the top level of the checkout cwd sits in.
//
// Only git's own LINE TERMINATOR is removed, not every trailing space.
// `rev-parse --show-toplevel` prints the path followed by "\n", and a path
// component may legitimately END in a space — a trailing space is an ordinary
// byte in a POSIX name, so `git clone … "~/work/checkout "` is a checkout like
// any other. strings.TrimSpace takes that byte along with the terminator and
// returns the name of a DIFFERENT directory, which usually is not on disk at all;
// callers that use the result as a boundary (internal/cli.confinementRoot) then
// classify every path in the real checkout as outside it.
func RepoRoot(ctx context.Context, cwd string) (string, error) {
	out, err := run(ctx, cwd, "git", "rev-parse", "--show-toplevel")
	if err != nil {
		return "", err
	}
	return strings.TrimSuffix(out, "\n"), nil
}

// RepoPrefix reports cwd's path from the repository root, including Git's
// trailing slash when non-empty. Git is authoritative here: linked worktrees,
// submodules, and unusual path bytes must use the same coordinate system as
// tree object expressions. Only Git's final LF is removed.
func RepoPrefix(ctx context.Context, cwd string) (string, error) {
	out, err := run(ctx, cwd, "git", "rev-parse", "--show-prefix")
	if err != nil {
		return "", err
	}
	return strings.TrimSuffix(out, "\n"), nil
}

// RepoCommandRoot returns a cwd from which tree-root-relative paths keep the
// same coordinates. A worktree subdirectory is normalized to Git's top level;
// a worktree root or bare repository already has an empty prefix and is kept as
// provided. This matters when rev itself is a subtree OID: running tree commands
// from the original subdirectory would apply that prefix a second time.
func RepoCommandRoot(ctx context.Context, cwd string) (string, error) {
	prefix, err := RepoPrefix(ctx, cwd)
	if err != nil {
		return "", err
	}
	if prefix == "" {
		return cwd, nil
	}
	return RepoRoot(ctx, cwd)
}

func repoTreePath(ctx context.Context, repo, path string) (string, error) {
	prefix, err := RepoPrefix(ctx, repo)
	if err != nil {
		return "", err
	}
	return prefix + path, nil
}

func RevParse(ctx context.Context, repo, rev string) (string, error) {
	// --verify --end-of-options: rev can be a caller-supplied label (e.g. a
	// diff --base/--head argument). Plain `git rev-parse --end-of-options
	// <rev>` still just ECHOES an option-shaped arg back on its own output
	// line instead of rejecting it (rev-parse's parseopt-style passthrough
	// for shell scripts) -- --verify is what turns "not a revision" into a
	// hard, single-line failure instead of a silently wrong resolution.
	out, err := run(ctx, repo, "git", "rev-parse", "--verify", "--end-of-options", rev)
	if err != nil {
		return "", err
	}
	return strings.TrimSpace(out), nil
}

// HeadCommitAndTree resolves HEAD and its root tree from one selected commit.
// Besides avoiding a second Git process on every committed cache probe, using
// one show operation prevents a concurrent HEAD update from mixing provenance
// from two different commits.
func HeadCommitAndTree(ctx context.Context, repo string) (string, string, error) {
	out, err := run(ctx, repo, "git", "show", "-s", "--no-show-signature", "--no-notes", "--format=%H%x00%T", "--end-of-options", "HEAD^{commit}")
	if err != nil {
		return "", "", err
	}
	commit, tree, ok := strings.Cut(strings.TrimSuffix(out, "\n"), "\x00")
	if !ok || commit == "" || tree == "" || strings.ContainsAny(commit, "\x00\r\n") || strings.ContainsAny(tree, "\x00\r\n") {
		return "", "", errors.New("git show returned malformed HEAD commit/tree metadata")
	}
	return commit, tree, nil
}

func FirstParent(ctx context.Context, repo, rev string) (string, error) {
	// --verify --end-of-options: rev is a caller-supplied revision label
	// (e.g. the `entire commit <rev>` CLI argument); guard it the same way
	// RevParse does.
	out, err := run(ctx, repo, "git", "rev-parse", "--verify", "--end-of-options", rev+"^")
	if err != nil {
		return "", fmt.Errorf("resolve first parent for %s: %w", rev, err)
	}
	return strings.TrimSpace(out), nil
}

func FindCommitWithCheckpoint(ctx context.Context, repo, checkpointID string) (string, error) {
	// --all includes detached HEADs from every linked worktree because a
	// checkpoint commit can be reachable only from one of them. --ignore-missing
	// keeps an unrelated invalid worktree HEAD from breaking the whole lookup.
	out, err := run(ctx, repo, "git", "log", "--ignore-missing", "--all", "--format=%H", "-n", "1", "--grep=Entire-Checkpoint: "+checkpointID)
	if err != nil {
		return "", err
	}
	commit := strings.TrimSpace(out)
	if commit == "" {
		return "", fmt.Errorf("checkpoint %s has no associated commit in this repository", checkpointID)
	}
	return commit, nil
}

func ListFiles(ctx context.Context, repo, rev string) ([]string, error) {
	out, err := run(ctx, repo, "git", "ls-tree", "-r", "-z", "--name-only", rev)
	if err != nil {
		return nil, err
	}
	var files []string
	for _, path := range strings.Split(out, "\x00") {
		if path != "" {
			files = append(files, path)
		}
	}
	return files, nil
}

// ListIndexFiles lists the tracked files of the working tree's git index
// (`git ls-files -z`), relative to repo. It runs one git subprocess for the
// whole listing; callers use it to decide tracked-ness without per-path git
// calls. A non-git directory returns an error.
func ListIndexFiles(ctx context.Context, repo string) ([]string, error) {
	return listBoundedWorktreePaths(newCmd(ctx, repo, "git", "ls-files", "-z"))
}

// ListWorktreeFiles lists the working tree the way Git itself sees it: tracked
// files plus untracked files that no exclude rule covers
// (`git ls-files --cached --others --exclude-standard`). Delegating the exclude
// decision to Git is the point — it applies nested .gitignore files,
// .git/info/exclude, and per-worktree excludes, none of which a hand-rolled
// reader of the repository-root .gitignore can see. Configuration-derived
// core.excludesFile is deliberately disabled because it can name an arbitrary
// off-volume or network path. Paths are relative to repo and returned in Git's
// order with duplicates removed; a non-git directory returns an error so callers
// can fall back to a filesystem walk.
func ListWorktreeFiles(ctx context.Context, repo string) ([]string, error) {
	return listBoundedWorktreePaths(newCmd(ctx, repo, "git", "ls-files", "-z", "--cached", "--others", "--exclude-standard"))
}

// ListIgnoredWorktreeFiles lists the untracked working-tree files Git's exclude
// rules *do* cover (`git ls-files --others --ignored --exclude-standard`). It
// exists for one caller: an explicit include-file whose negations re-include
// paths the project gitignores. Nothing else should enumerate ignored content —
// that is the tree whose size is the reason the exclude rules exist.
func ListIgnoredWorktreeFiles(ctx context.Context, repo string) ([]string, error) {
	return listBoundedWorktreePaths(newCmd(ctx, repo, "git", "ls-files", "-z", "--others", "--ignored", "--exclude-standard"))
}

const (
	maxWorktreeListingFields = 1_000_000
	maxWorktreeListingBytes  = 256 << 20
)

// ErrWorktreeListingTruncated reports that a provider/index path listing
// exceeded its fixed discovery bound. Callers must not reinterpret this as an
// ordinary Git failure and retry through another unbounded listing path.
var ErrWorktreeListingTruncated = errors.New("Git worktree listing exceeded a raw-output bound")

type worktreeListingBudget struct {
	fields int
	bytes  int
}

func (b *worktreeListingBudget) admit(path string) bool {
	if b.fields >= maxWorktreeListingFields {
		return false
	}
	recordBytes := len(path) + 1
	if recordBytes > maxWorktreeListingBytes-b.bytes {
		return false
	}
	b.fields++
	b.bytes += recordBytes
	return true
}

func listBoundedWorktreePaths(cmd *exec.Cmd) ([]string, error) {
	paths := make([]string, 0)
	seen := make(map[string]struct{})
	err := visitBoundedWorktreePathOutput(cmd, func(path string) bool {
		if path == "" {
			return true
		}
		if _, duplicate := seen[path]; duplicate {
			return true
		}
		seen[path] = struct{}{}
		paths = append(paths, path)
		return true
	})
	if err != nil {
		return nil, err
	}
	return paths, nil
}

// visitBoundedWorktreePathOutput applies the fixed raw count and byte budget
// before the caller sees each record. In particular, a visitor that discards
// ignored or otherwise ineligible records cannot accidentally turn a bounded
// retained set into an unbounded Git stdout stream.
func visitBoundedWorktreePathOutput(cmd *exec.Cmd, visit func(string) bool) error {
	var budget worktreeListingBudget
	return visitBoundedWorktreePathOutputWithBudget(cmd, &budget, visit)
}

func visitBoundedWorktreePathOutputWithBudget(cmd *exec.Cmd, budget *worktreeListingBudget, visit func(string) bool) error {
	truncated := false
	err := visitBoundedNULPaths(cmd, func(path string) bool {
		if !budget.admit(path) {
			truncated = true
			return false
		}
		return visit(path)
	})
	if err != nil {
		return err
	}
	if truncated {
		return ErrWorktreeListingTruncated
	}
	return nil
}

// keepDirectoryEntry keeps only trailing-slash, not-yet-seen fields from a
// streamed `git ls-files --directory` response.
func keepDirectoryEntry(field string, seen map[string]struct{}) bool {
	if field == "" || !strings.HasSuffix(field, "/") {
		return false
	}
	if _, exists := seen[field]; exists {
		return false
	}
	seen[field] = struct{}{}
	return true
}

// maxIgnoredDirectoryFields and maxIgnoredDirectoryBytes bound the total
// NUL-delimited records VisitWorktreeDirectoryEntries will read from Git
// before giving up on the listing, independent of how many of those records
// turn out to be directory entries kept by keepDirectoryEntry. The byte bound
// includes each record's NUL delimiter, so even a stream of maximum-size path
// records has a fixed aggregate I/O ceiling.
//
// `--directory` only collapses a directory when git's own listing classifies
// its ENTIRE content the same way (see keepDirectoryEntry). A directory
// ignored only by a file-pattern rule (`*.o`, `node_modules/*.log`)
// alongside other content is never collapsed, so git instead prints one
// field per matched FILE — potentially millions, entirely controlled by the
// scanned repository's own committed `.gitignore` — while the number of
// fields this loop actually KEEPS can stay at zero. Filtering as each field
// arrives (rather than buffering the whole listing) already bounds this
// call's cost to the number of directories in the ordinary case, but a
// scanned repository that arranges for zero collapsible directories among
// millions of pattern-ignored files still makes this loop read and discard
// every one of them before the caller's OWN directory budget
// (defaultSweepDirectoryBudget) ever gets a chance to apply — unbounded CPU
// and pipe I/O on every worktree query, ahead of the budget that exists
// specifically to prevent that.
//
// 2,000,000 fields and 64 MiB comfortably clear both the exact field-bound
// fixture and TestStreamNULDirectoryEntriesHandlesLargeMixedOutput's roughly
// 13 MiB, 1,000,003-field fixture (an ordinary large listing must not be
// truncated) while still turning "unbounded" into "bounded" for the
// adversarial case.
// Exceeding either limit kills the subprocess and reports the listing
// incomplete via errIgnoredListingTruncated, which the caller (gitSweepRoots)
// already treats exactly like a failed listing — falling back to the sweep's
// own budgeted, already-observed-directory derivation instead of trusting a
// partial one as if it were complete.
const (
	maxIgnoredDirectoryFields = 2_000_000
	maxIgnoredDirectoryBytes  = 64 << 20
)

// errIgnoredListingTruncated reports that the streamed directory listing stopped
// before EOF because a raw field-count or aggregate-byte bound was reached.
// It is a deliberate, fail-closed refusal to keep reading, not a process
// failure — callers should treat it exactly like any other error from this
// listing (gitSweepRoots already does, via a plain non-nil check).
var errIgnoredListingTruncated = errors.New("ignored-directory listing exceeded a raw-output bound")

type ignoredDirectoryListingBudget struct {
	fields int
	bytes  int
}

func (b *ignoredDirectoryListingBudget) admit(field string) bool {
	if b.fields >= maxIgnoredDirectoryFields {
		return false
	}
	recordBytes := len(field) + 1 // Include the NUL delimiter read from Git.
	if recordBytes > maxIgnoredDirectoryBytes-b.bytes {
		return false
	}
	b.fields++
	b.bytes += recordBytes
	return true
}

// GrepIndexMatches returns a bounded sample of matched terms per tracked
// worktree file. Fixed strings and NUL-delimited paths keep query terms and
// unusual paths from changing grep semantics.
func GrepIndexMatches(ctx context.Context, repo string, patterns []string, maxPerFile int) ([]GrepMatch, error) {
	return grepFixedStringMatches(ctx, repo, "", patterns, maxPerFile)
}

// GrepTreeMatches returns a bounded sample of matched fixed strings per file
// from an immutable Git tree. The returned paths are relative to repo and do
// not include Git's "<treeish>:" display prefix. Query strings are always
// passed as fixed-string patterns and paths are NUL-delimited, so neither can
// change grep or path parsing semantics.
func GrepTreeMatches(ctx context.Context, repo, treeish string, patterns []string, maxPerFile int) ([]GrepMatch, error) {
	if treeish == "" {
		return nil, errors.New("git grep treeish cannot be empty")
	}
	if strings.HasPrefix(treeish, "-") || strings.ContainsRune(treeish, '\x00') {
		return nil, fmt.Errorf("invalid git grep treeish %q", treeish)
	}
	return grepFixedStringMatches(ctx, repo, treeish, patterns, maxPerFile)
}

// GrepTreePaths returns every file in an immutable Git tree that contains at
// least one of the fixed-string patterns. Git emits each path once in
// NUL-delimited form, avoiding both matched-text fanout and ambiguity from
// unusual path bytes.
//
// It passes -I, so a blob Git itself classifies as binary (a NUL byte early
// in the content, or a `.gitattributes` binary/-diff marking) is silently
// excluded from the result even if it contains a matching pattern. That
// makes this preselection a strict superset of a text-only match, but NOT of
// every possible match in the tree -- callers that need every matching file
// regardless of Git's binary heuristic must use GrepTreePathsIncludingBinary.
func GrepTreePaths(ctx context.Context, repo, treeish string, patterns []string) ([]string, error) {
	if treeish == "" {
		return nil, errors.New("git grep treeish cannot be empty")
	}
	return grepTreePaths(ctx, repo, treeish, patterns, true, false)
}

// GrepTreePathsIncludingBinary behaves exactly like GrepTreePaths except it
// omits -I, so a file Git classifies as binary (an early NUL byte, or a
// `.gitattributes` binary/-diff marking) is still searched and can appear in
// the result. Use this when a caller's correctness requires a genuine strict
// superset of every file that contains a matching pattern, regardless of
// Git's binary heuristic -- e.g. a prefilter ahead of a parser that reads
// raw file content directly and does not care whether Git thinks the file is
// binary.
func GrepTreePathsIncludingBinary(ctx context.Context, repo, treeish string, patterns []string) ([]string, error) {
	if treeish == "" {
		return nil, errors.New("git grep treeish cannot be empty")
	}
	return grepTreePaths(ctx, repo, treeish, patterns, false, false)
}

// GrepTreePathsCaseSensitiveIncludingBinary behaves like
// GrepTreePathsIncludingBinary but matches case-sensitively. It exists for
// identifier prefilters: a case-sensitive substring match is still a strict
// superset of a case-sensitive whole-identifier check, while excluding files
// that only contain the pattern in a different case. Deliberately NOT -w:
// git grep's word-boundary mode leaves the multi-pattern fixed-string fast
// path and is orders of magnitude slower with hundreds of patterns (measured
// 5s vs 0.06s on a ~2.6k-file tree with 234 patterns).
func GrepTreePathsCaseSensitiveIncludingBinary(ctx context.Context, repo, treeish string, patterns []string) ([]string, error) {
	if treeish == "" {
		return nil, errors.New("git grep treeish cannot be empty")
	}
	return grepTreePaths(ctx, repo, treeish, patterns, false, true)
}

// GrepFixedStringPaths returns every file containing one exact, case-sensitive string. An empty
// treeish greps the working tree (what a worktree search indexes); a non-empty one greps that
// immutable tree.
//
// It exists for the repository-wide literal lookup in search: one needle, exact case, and the
// caller reads the matched files itself to get line numbers, so no output parsing beyond the
// NUL-delimited path list this package already does.
func GrepFixedStringPaths(ctx context.Context, repo, treeish, pattern string) ([]string, error) {
	if pattern == "" {
		return []string{}, nil
	}
	return grepTreePaths(ctx, repo, treeish, []string{pattern}, false, true)
}

